// Package gitleaksrules scans unified diffs with the gitleaks default ruleset
// embedded in the gk binary, so secret scanning works without the gitleaks
// binary installed.
//
// rules.json is generated by tools/genrules from a pinned gitleaks release
// (see `make gen-rules`). The engine mirrors the gitleaks detection steps
// that the default config relies on: keyword prefilter, regex, secret group,
// entropy, path rules, and global and per-rule allowlists.
package gitleaksrules

import (
	_ "embed"
	"encoding/json"
	"math"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"sync"

	"github.com/x-mesh/gk/internal/secrets"
)

//go:embed rules.json
var rulesJSON []byte

type ruleset struct {
	Source    source     `json:"source"`
	Allowlist allowlist  `json:"allowlist"`
	Rules     []jsonRule `json:"rules"`
}

type source struct {
	GitleaksVersion string `json:"gitleaksVersion"`
}

type allowlist struct {
	Paths     []string `json:"paths"`
	Regexes   []string `json:"regexes"`
	Stopwords []string `json:"stopwords"`
}

type jsonRule struct {
	ID          string          `json:"id"`
	Regex       string          `json:"regex"`
	Path        string          `json:"path"`
	Keywords    []string        `json:"keywords"`
	Entropy     float64         `json:"entropy"`
	SecretGroup int             `json:"secretGroup"`
	Allowlists  []jsonRuleAllow `json:"allowlists"`
}

type jsonRuleAllow struct {
	Condition   string   `json:"condition"`
	RegexTarget string   `json:"regexTarget"`
	Regexes     []string `json:"regexes"`
	Paths       []string `json:"paths"`
	Stopwords   []string `json:"stopwords"`
}

type ruleAllow struct {
	and       bool
	target    string
	regexes   []*regexp.Regexp
	paths     []*regexp.Regexp
	stopwords []string
}

type rule struct {
	id          string
	regex       *regexp.Regexp
	path        *regexp.Regexp
	keywords    []string
	entropy     float64
	secretGroup int
	allowlists  []ruleAllow
}

type engine struct {
	version         string
	globalPaths     []*regexp.Regexp
	globalRegexes   []*regexp.Regexp
	globalStopwords []string
	rules           []rule
}

var (
	loadOnce sync.Once
	loaded   *engine
)

// Version returns the gitleaks release the embedded ruleset came from.
func Version() string { return get().version }

// RuleCount returns the number of embedded rules.
func RuleCount() int { return len(get().rules) }

// get compiles the ruleset on first use so commands that never scan do not
// pay for compiling hundreds of regexes.
func get() *engine {
	loadOnce.Do(func() {
		var rs ruleset
		if err := json.Unmarshal(rulesJSON, &rs); err != nil {
			panic("gitleaksrules: corrupt embedded rules.json: " + err.Error())
		}
		loaded = compile(rs)
	})
	return loaded
}

// mustCompile panics on a bad pattern: genrules already rejected every
// pattern, so a failure here means the embedded file was altered by hand.
func mustCompile(p string) *regexp.Regexp {
	if p == "" {
		return nil
	}
	return regexp.MustCompile(p)
}

func mustCompileAll(ps []string) []*regexp.Regexp {
	out := make([]*regexp.Regexp, 0, len(ps))
	for _, p := range ps {
		out = append(out, regexp.MustCompile(p))
	}
	return out
}

func lowerAll(ss []string) []string {
	out := make([]string, len(ss))
	for i, s := range ss {
		out[i] = strings.ToLower(s)
	}
	return out
}

func compile(rs ruleset) *engine {
	e := &engine{
		version:         rs.Source.GitleaksVersion,
		globalPaths:     mustCompileAll(rs.Allowlist.Paths),
		globalRegexes:   mustCompileAll(rs.Allowlist.Regexes),
		globalStopwords: lowerAll(rs.Allowlist.Stopwords),
	}
	for _, jr := range rs.Rules {
		r := rule{
			id:          jr.ID,
			regex:       mustCompile(jr.Regex),
			path:        mustCompile(jr.Path),
			keywords:    lowerAll(jr.Keywords),
			entropy:     jr.Entropy,
			secretGroup: jr.SecretGroup,
		}
		for _, ja := range jr.Allowlists {
			r.allowlists = append(r.allowlists, ruleAllow{
				and:       ja.Condition == "AND",
				target:    ja.RegexTarget,
				regexes:   mustCompileAll(ja.Regexes),
				paths:     mustCompileAll(ja.Paths),
				stopwords: lowerAll(ja.Stopwords),
			})
		}
		e.rules = append(e.rules, r)
	}
	return e
}

// ScanDiff scans the added lines of a unified diff (`git diff` or
// `git log -p` output) and returns one finding per matched secret.
func ScanDiff(diff string) []secrets.Finding { return get().scanDiff(diff) }

func (e *engine) scanDiff(diff string) []secrets.Finding {
	var out []secrets.Finding
	for _, f := range parseDiff(diff) {
		if f.path == "" || matchAny(e.globalPaths, f.path) {
			continue
		}
		var fileFindings []secrets.Finding
		for _, r := range e.rules {
			if r.path != nil && !r.path.MatchString(f.path) {
				continue
			}
			if r.regex == nil {
				// gitleaks reports a path-only match at line 0.
				fileFindings = append(fileFindings, secrets.Finding{Kind: r.id, File: f.path})
				continue
			}
			for _, h := range f.hunks {
				fileFindings = append(fileFindings, e.scanHunk(r, f.path, h)...)
			}
		}
		out = append(out, dropShadowedGeneric(fileFindings)...)
	}
	return out
}

const genericRuleID = "generic-api-key"

// dropShadowedGeneric removes a generic-api-key finding when a more specific
// rule matched on the same line, because gitleaks reports the specific rule
// only. Observed against gitleaks 8.30.1, not taken from its source.
func dropShadowedGeneric(fs []secrets.Finding) []secrets.Finding {
	specific := map[int]bool{}
	for _, f := range fs {
		if f.Kind != genericRuleID {
			specific[f.FileLine] = true
		}
	}
	out := fs[:0]
	for _, f := range fs {
		if f.Kind == genericRuleID && specific[f.FileLine] {
			continue
		}
		out = append(out, f)
	}
	return out
}

func (e *engine) scanHunk(r rule, path string, h hunk) []secrets.Finding {
	text := h.joined
	if len(r.keywords) > 0 && !containsAny(h.lower, r.keywords) {
		return nil
	}
	var out []secrets.Finding
	for _, loc := range r.regex.FindAllStringSubmatchIndex(text, -1) {
		match := text[loc[0]:loc[1]]
		secret := pickSecret(text, loc, r.secretGroup)
		if r.entropy > 0 && shannon(secret) < r.entropy {
			continue
		}
		line := h.lineAt(loc[0])
		if e.allowed(r, path, secret, match, h.lineText(line)) {
			continue
		}
		out = append(out, secrets.Finding{
			Kind:     r.id,
			File:     path,
			FileLine: h.fileLine(line),
			Line:     h.fileLine(line),
			Sample:   maskSecret(secret),
		})
	}
	return out
}

// pickSecret follows the gitleaks rule: an explicit secretGroup wins, then the
// first non-empty capture group, then the whole match.
func pickSecret(text string, loc []int, group int) string {
	if group > 0 && 2*group+1 < len(loc) && loc[2*group] >= 0 {
		return text[loc[2*group]:loc[2*group+1]]
	}
	for g := 1; 2*g+1 < len(loc); g++ {
		if loc[2*g] >= 0 && loc[2*g] != loc[2*g+1] {
			return text[loc[2*g]:loc[2*g+1]]
		}
	}
	return text[loc[0]:loc[1]]
}

func (e *engine) allowed(r rule, path, secret, match, line string) bool {
	if matchAny(e.globalRegexes, secret) || hasStopword(e.globalStopwords, secret) {
		return true
	}
	for _, a := range r.allowlists {
		if a.allows(path, secret, match, line) {
			return true
		}
	}
	return false
}

func (a ruleAllow) allows(path, secret, match, line string) bool {
	target := secret
	switch a.target {
	case "match":
		target = match
	case "line":
		target = line
	}
	var results []bool
	if len(a.paths) > 0 {
		results = append(results, matchAny(a.paths, path))
	}
	if len(a.regexes) > 0 {
		results = append(results, matchAny(a.regexes, target))
	}
	if len(a.stopwords) > 0 {
		results = append(results, hasStopword(a.stopwords, secret))
	}
	if len(results) == 0 {
		return false
	}
	for _, ok := range results {
		if a.and && !ok {
			return false
		}
		if !a.and && ok {
			return true
		}
	}
	return a.and
}

func matchAny(res []*regexp.Regexp, s string) bool {
	for _, re := range res {
		if re.MatchString(s) {
			return true
		}
	}
	return false
}

func hasStopword(lowerWords []string, s string) bool {
	l := strings.ToLower(s)
	for _, w := range lowerWords {
		if strings.Contains(l, w) {
			return true
		}
	}
	return false
}

func containsAny(lower string, words []string) bool {
	for _, w := range words {
		if strings.Contains(lower, w) {
			return true
		}
	}
	return false
}

func shannon(s string) float64 {
	if s == "" {
		return 0
	}
	freq := map[rune]float64{}
	n := 0.0
	for _, r := range s {
		freq[r]++
		n++
	}
	var h float64
	for _, c := range freq {
		p := c / n
		h -= p * math.Log2(p)
	}
	return h
}

func maskSecret(s string) string {
	if len(s) <= 4 {
		return strings.Repeat("*", len(s))
	}
	stars := min(len(s)-4, 8)
	return s[:4] + strings.Repeat("*", stars)
}

type fileDiff struct {
	path  string
	hunks []hunk
}

// hunk holds the added lines of one @@ hunk. gitleaks scans the same unit:
// added lines of a hunk joined by newlines.
type hunk struct {
	lines   []string
	numbers []int
	joined  string
	lower   string
}

// lineAt maps a byte offset in the joined text to an index into lines.
func (h hunk) lineAt(offset int) int {
	pos := 0
	starts := make([]int, len(h.lines))
	for i, l := range h.lines {
		starts[i] = pos
		pos += len(l) + 1
	}
	return sort.Search(len(starts), func(i int) bool { return starts[i] > offset }) - 1
}

func (h hunk) lineText(i int) string {
	if i < 0 || i >= len(h.lines) {
		return ""
	}
	return h.lines[i]
}

func (h hunk) fileLine(i int) int {
	if i < 0 || i >= len(h.numbers) {
		return 0
	}
	return h.numbers[i]
}

var hunkHeader = regexp.MustCompile(`^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@`)

// parseDiff splits a unified diff into per-file added-line hunks. A file with
// no added lines (a binary file or a pure rename) is still returned so
// path-only rules such as pkcs12-file can match it.
func parseDiff(diff string) []fileDiff {
	var files []fileDiff
	var cur *fileDiff
	var h *hunk
	newLine := 0
	flush := func() {
		if h != nil && len(h.lines) > 0 && cur != nil {
			h.joined = strings.Join(h.lines, "\n")
			h.lower = strings.ToLower(h.joined)
			cur.hunks = append(cur.hunks, *h)
		}
		h = nil
	}
	for line := range strings.SplitSeq(diff, "\n") {
		switch {
		case strings.HasPrefix(line, "diff --git "):
			flush()
			files = append(files, fileDiff{path: pathFromGitHeader(line)})
			cur = &files[len(files)-1]
		case cur == nil:
		case strings.HasPrefix(line, "+++ "):
			rest := line[len("+++ "):]
			if rest == "/dev/null" {
				cur.path = ""
			} else if p, ok := postImagePath(rest); ok {
				cur.path = p
			}
		case strings.HasPrefix(line, "@@"):
			flush()
			if m := hunkHeader.FindStringSubmatch(line); m != nil {
				newLine, _ = strconv.Atoi(m[1])
				h = &hunk{}
			}
		case h == nil:
		case strings.HasPrefix(line, "+"):
			h.lines = append(h.lines, line[1:])
			h.numbers = append(h.numbers, newLine)
			newLine++
		case strings.HasPrefix(line, " "):
			newLine++
		}
	}
	flush()
	return files
}

func pathFromGitHeader(line string) string {
	if i := strings.LastIndex(line, ` "b/`); i >= 0 {
		p, _ := postImagePath(line[i+1:])
		return p
	}
	if i := strings.LastIndex(line, " b/"); i >= 0 {
		return line[i+3:]
	}
	return ""
}

// postImagePath extracts the file path from a `b/<path>` header token. Git
// wraps a name that holds a quote, backslash, control character, or (with
// core.quotePath) non-ASCII byte in a C-style quoted string, and it appends a
// tab to an unquoted name that holds a space. Skipping a quoted name would
// silently drop that file from the scan.
func postImagePath(token string) (string, bool) {
	if strings.HasPrefix(token, `"`) {
		unq, err := strconv.Unquote(token)
		if err != nil {
			return "", false
		}
		token = unq
	} else {
		token = strings.TrimRight(token, "\t")
	}
	return strings.CutPrefix(token, "b/")
}
